import{_ as t,o as a,c as o,aj as s}from"./chunks/framework.C6uXqnaX.js";const m=JSON.parse('{"title":"Composing Components","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"tutorials/learn-angular/3-composing-components.md","filePath":"tutorials/learn-angular/3-composing-components.md"}'),n={name:"tutorials/learn-angular/3-composing-components.md"};function p(i,e,l,c,r,d){return a(),o("div",null,e[0]||(e[0]=[s('<h1 id="composing-components" tabindex="-1">Composing Components <a class="header-anchor" href="#composing-components" aria-label="Permalink to &quot;Composing Components&quot;">​</a></h1><p>You&#39;ve learned to update the component template, component logic, and component styles, but how do you use a component in your application?</p><p>The <code>selector</code> property of the component configuration gives you a name to use when referencing the component in another template. You use the <code>selector</code> like an HTML tag, for example <code>app-user</code> would be <code>&lt;app-user /&gt;</code> in the template.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Learn more about <a href="/essentials/components#using-components">using components in the essentials guide</a>.</p></div><p>In this activity, you&#39;ll learn how to compose components.</p><hr><p>In this example, there are two components <code>User</code> and <code>App</code>.</p><h3 id="_1-add-a-reference-to-user" tabindex="-1">1. Add a reference to <code>User</code> <a class="header-anchor" href="#_1-add-a-reference-to-user" aria-label="Permalink to &quot;1. Add a reference to `User`&quot;">​</a></h3><p>Update the <code>App</code> template to include a reference to the <code>User</code> which uses the selector <code>app-user</code>. Be sure to add <code>User</code> to the imports array of <code>App</code>, this makes it available for use in the <code>App</code> template.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template: `&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">app-user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;`, imports: [User]</span></span></code></pre></div><p>The component now displays the message <code>Username: youngTech</code>. You can update the template code to include more markup.</p><h3 id="_2-add-more-markup" tabindex="-1">2. Add more markup <a class="header-anchor" href="#_2-add-more-markup" aria-label="Permalink to &quot;2. Add more markup&quot;">​</a></h3><p>Because you can use any HTML markup that you want in a template, try updating the template for <code>App</code> to also include more HTML elements. This example will add a <code>&lt;section&gt;</code> element as the parent of the <code>&lt;app-user&gt;</code> element.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template: `</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">section</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">app-user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">section</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">`,</span></span></code></pre></div><p>You can use as much HTML markup and as many components as you need to bring your app idea to reality. You can even have multiple copies of your component on the same page.</p><p>That&#39;s a great segue, how would you conditionally show a component based on data? Head to the next section to find out.</p>',16)]))}const u=t(n,[["render",p]]);export{m as __pageData,u as default};
